import { useState, useRef } from 'react';
import { uploadAvatar, updateUser } from '@/lib/api';

const ALLOWED_TYPES = ['image/jpeg', 'image/png', 'image/gif'];
const MAX_SIZE = 5 * 1024 * 1024; // 5MB

export function AvatarUpload({ userId, currentAvatar, onUpdate }) {
  const [preview, setPreview] = useState<string | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [error, setError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0];
    if (!selected) return;

    if (!ALLOWED_TYPES.includes(selected.type)) {
      setError('Please select a JPG, PNG, or GIF image');
      return;
    }
    if (selected.size > MAX_SIZE) {
      setError('File must be under 5MB');
      return;
    }

    setError(null);
    setFile(selected);
    setPreview(URL.createObjectURL(selected));
  };

  const handleUpload = async () => {
    if (!file) return;
    const { url } = await uploadAvatar(file);
    await updateUser(userId, { avatarUrl: url });
    onUpdate(url);
    setFile(null);
    setPreview(null);
  };

  return (
    <div>
      <img src={preview || currentAvatar} alt="Avatar" />
      <input ref={inputRef} type="file" accept="image/*" onChange={handleSelect} hidden />
      <button onClick={() => inputRef.current?.click()}>Choose Image</button>
      {preview && <button onClick={handleUpload}>Upload</button>}
      {error && <p className="text-red-500">{error}</p>}
    </div>
  );
}
```

**api.ts addition**
```typescript
export async function uploadAvatar(file: File): Promise<{ url: string }> {
  const formData = new FormData();
  formData.append('file', file);
  const res = await fetch('/api/upload', { method: 'POST', body: formData });
  return res.json();
}
```

