import { useState } from 'react';
import { useToast } from '@/hooks/useToast';
import { useAuth } from '@/hooks/useAuth';
import { updatePreferences } from '@/lib/api';

const NOTIFICATION_TYPES = [
  { key: 'marketing', label: 'Marketing emails', description: 'Product announcements and offers' },
  { key: 'updates', label: 'Product updates', description: 'New features and improvements' },
  { key: 'security', label: 'Security alerts', description: 'Login alerts and security notices' },
];

export function NotificationPreferences() {
  const { user } = useAuth();
  const { toast } = useToast();
  const [preferences, setPreferences] = useState(user.notificationPreferences);
  const [isSaving, setIsSaving] = useState(false);

  const handleToggle = (key: string) => {
    setPreferences(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await updatePreferences(user.id, preferences);
      toast({ title: 'Preferences saved', variant: 'success' });
    } catch (e) {
      toast({ title: 'Failed to save', variant: 'error' });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <section>
      <h2>Email Notifications</h2>
      {NOTIFICATION_TYPES.map(({ key, label, description }) => (
        <label key={key} className="flex items-center gap-2">
          <input
            type="checkbox"
            checked={preferences[key]}
            onChange={() => handleToggle(key)}
          />
          <div>
            <p>{label}</p>
            <p className="text-sm text-gray-500">{description}</p>
          </div>
        </label>
      ))}
      <button onClick={handleSave} disabled={isSaving}>
        {isSaving ? 'Saving...' : 'Save Preferences'}
      </button>
    </section>
