import { useState } from 'react';
import { QRCodeSVG } from 'qrcode.react';

type Step = 'initial' | 'scan' | 'verify' | 'backup' | 'enabled';

export function TwoFactorSetup({ isEnabled, onUpdate }) {
  const [step, setStep] = useState<Step>(isEnabled ? 'enabled' : 'initial');
  const [qrCodeUrl, setQrCodeUrl] = useState('');
  const [backupCodes, setBackupCodes] = useState<string[]>([]);
  const [code, setCode] = useState('');
  const [error, setError] = useState('');

  const startSetup = async () => {
    const res = await fetch('/api/auth/2fa/setup', { method: 'POST' });
    const data = await res.json();
    setQrCodeUrl(data.qrCodeUrl);
    setStep('scan');
  };

  const verifyCode = async () => {
    const res = await fetch('/api/auth/2fa/verify', {
      method: 'POST',
      body: JSON.stringify({ code }),
    });

    if (res.ok) {
      const { backupCodes } = await res.json();
      setBackupCodes(backupCodes);
      setStep('backup');
    } else {
      setError('Invalid code. Please try again.');
    }
  };

  const disable2FA = async () => {
    await fetch('/api/auth/2fa', { method: 'DELETE' });
    onUpdate(false);
    setStep('initial');
  };

  if (step === 'initial') {
    return <button onClick={startSetup}>Enable Two-Factor Authentication</button>;
  }

  if (step === 'scan') {
    return (
      <div>
        <h3>Scan QR Code</h3>
        <QRCodeSVG value={qrCodeUrl} size={200} />
        <button onClick={() => setStep('verify')}>Next</button>
      </div>
    );
  }

  if (step === 'verify') {
    return (
      <div>
        <h3>Enter Verification Code</h3>
        <input
          type="text"
          maxLength={6}
          value={code}
          onChange={e => setCode(e.target.value)}
          placeholder="000000"
        />
        {error && <p className="text-red-500">{error}</p>}
        <button onClick={verifyCode}>Verify</button>
      </div>
    );
  }

  if (step === 'backup') {
    return (
      <div>
        <h3>Save Backup Codes</h3>
        <p>Store these codes safely. Each can only be used once.</p>
        <ul className="font-mono">
          {backupCodes.map((code, i) => <li key={i}>{code}</li>)}
        </ul>
        <button onClick={() => { setStep('enabled'); onUpdate(true); }}>Done</button>
      </div>
    );
  }

  return (
    <div>
      <p className="text-green-600">Two-factor authentication is enabled</p>
      <button onClick={disable2FA} className="text-red-600">Disable 2FA</button>
    </div>
  );
}
```

