import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { GripVertical } from 'lucide-react';

function SortableTask({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div ref={setNodeRef} style={style} className="flex items-center gap-2 p-2 bg-white border rounded">
      <button {...attributes} {...listeners} className="cursor-grab">
        <GripVertical className="text-gray-400" />
      </button>
      <span>{task.title}</span>
    </div>
  );
}

export function TaskList() {
  const queryClient = useQueryClient();
  const { data: tasks } = useQuery({ queryKey: ['tasks'], queryFn: fetchTasks });
  const [activeId, setActiveId] = useState(null);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  const reorderMutation = useMutation({
    mutationFn: (taskIds: string[]) =>
      fetch('/api/tasks/reorder', {
        method: 'PATCH',
        body: JSON.stringify({ taskIds }),
      }),
    onMutate: async (newOrder) => {
      await queryClient.cancelQueries({ queryKey: ['tasks'] });
      const previous = queryClient.getQueryData(['tasks']);

      // Optimistic update
      queryClient.setQueryData(['tasks'], (old) =>
        newOrder.map(id => old.find(t => t.id === id))
      );

      return { previous };
    },
    onError: (err, newOrder, context) => {
      // Rollback on error
      queryClient.setQueryData(['tasks'], context.previous);
    },
  });

  const handleDragEnd = (event) => {
    const { active, over } = event;
    setActiveId(null);

    if (active.id !== over?.id) {
      const oldIndex = tasks.findIndex(t => t.id === active.id);
      const newIndex = tasks.findIndex(t => t.id === over.id);
      const newOrder = arrayMove(tasks, oldIndex, newIndex).map(t => t.id);
      reorderMutation.mutate(newOrder);
    }
  };

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragStart={(e) => setActiveId(e.active.id)}
      onDragEnd={handleDragEnd}
    >
      <SortableContext items={tasks.map(t => t.id)} strategy={verticalListSortingStrategy}>
        <div className="space-y-2">
          {tasks.map(task => <SortableTask key={task.id} task={task} />)}
        </div>
      </SortableContext>

      <DragOverlay>
        {activeId ? <TaskCard task={tasks.find(t => t.id === activeId)} /> : null}
      </DragOverlay>
    </DndContext>
  );
}
```

