import { useState, useRef, useEffect } from 'react';

interface EditableCellProps {
  value: string;
  row: { id: string };
  column: { id: string };
  onSave: (id: string, field: string, value: string) => Promise<void>;
  validate?: (value: string) => string | null;
}

export function EditableCell({ value: initialValue, row, column, onSave, validate }: EditableCellProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [value, setValue] = useState(initialValue);
  const [error, setError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setValue(initialValue);
  }, [initialValue]);

  useEffect(() => {
    if (isEditing) {
      inputRef.current?.focus();
      inputRef.current?.select();
    }
  }, [isEditing]);

  const handleSave = async () => {
    if (validate) {
      const validationError = validate(value);
      if (validationError) {
        setError(validationError);
        return;
      }
    }

    if (value !== initialValue) {
      await onSave(row.id, column.id, value);
    }
    setIsEditing(false);
    setError(null);
  };

  const handleCancel = () => {
    setValue(initialValue);
    setIsEditing(false);
    setError(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSave();
    } else if (e.key === 'Escape') {
      handleCancel();
    }
  };

  if (!isEditing) {
    return (
      <div
        onDoubleClick={() => setIsEditing(true)}
        className="cursor-pointer hover:bg-gray-50 p-1 rounded"
      >
        {value || <span className="text-gray-400">-</span>}
      </div>
    );
  }

  return (
    <div>
      <input
        ref={inputRef}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={handleSave}
        className={`w-full p-1 border rounded ${error ? 'border-red-500' : 'border-blue-500'}`}
      />
      {error && <p className="text-xs text-red-500">{error}</p>}
    </div>
  );
}
```

