import { Knex } from 'knex';

export async function up(knex: Knex): Promise<void> {
  // Check if index exists before creating
  const hasEmailIndex = await knex.schema.raw(`
    SELECT 1 FROM pg_indexes 
    WHERE tablename = 'users' AND indexname = 'idx_users_email'
  `).then(r => r.rows.length > 0);

  if (!hasEmailIndex) {
    await knex.schema.alterTable('users', (table) => {
      table.index('email', 'idx_users_email');
    });
    console.log('Created index: idx_users_email');
  } else {
    console.log('Index idx_users_email already exists, skipping');
  }

  // Composite index on orders
  const hasOrdersIndex = await knex.schema.raw(`
    SELECT 1 FROM pg_indexes 
    WHERE tablename = 'orders' AND indexname = 'idx_orders_user_created'
  `).then(r => r.rows.length > 0);

  if (!hasOrdersIndex) {
    await knex.schema.alterTable('orders', (table) => {
      table.index(['user_id', 'created_at'], 'idx_orders_user_created');
    });
    console.log('Created index: idx_orders_user_created');
  } else {
    console.log('Index idx_orders_user_created already exists, skipping');
  }
}

export async function down(knex: Knex): Promise<void> {
  // Drop indexes if they exist
  await knex.schema.raw(`
    DROP INDEX IF EXISTS idx_users_email;
    DROP INDEX IF EXISTS idx_orders_user_created;
  `);

  console.log('Dropped indexes: idx_users_email, idx_orders_user_created');
}
