import { useState, useMemo } from 'react';
import * as Popover from '@radix-ui/react-popover';
import { Check, ChevronDown, X } from 'lucide-react';

interface Option {
  value: string;
  label: string;
}

interface MultiSelectProps {
  options: Option[];
  selected: string[];
  onChange: (selected: string[]) => void;
  placeholder?: string;
}

export function MultiSelect({
  options,
  selected,
  onChange,
  placeholder = 'Select...',
}: MultiSelectProps) {
  const [search, setSearch] = useState('');
  const [focusIndex, setFocusIndex] = useState(0);
  const [isOpen, setIsOpen] = useState(false);

  const filteredOptions = useMemo(() =>
    options.filter(opt =>
      opt.label.toLowerCase().includes(search.toLowerCase())
    ),
    [options, search]
  );

  const toggleOption = (value: string) => {
    if (selected.includes(value)) {
      onChange(selected.filter(v => v !== value));
    } else {
      onChange([...selected, value]);
    }
  };

  const clearAll = () => {
    onChange([]);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setFocusIndex(i => Math.min(i + 1, filteredOptions.length - 1));
        break;
      case 'ArrowUp':
        e.preventDefault();
        setFocusIndex(i => Math.max(i - 1, 0));
        break;
      case 'Enter':
        e.preventDefault();
        if (filteredOptions[focusIndex]) {
          toggleOption(filteredOptions[focusIndex].value);
        }
        break;
      case 'Escape':
        setIsOpen(false);
        break;
    }
  };

  const buttonText = selected.length > 0
    ? `${selected.length} selected`
    : placeholder;

  return (
    <Popover.Root open={isOpen} onOpenChange={setIsOpen}>
      <Popover.Trigger asChild>
        <button className="flex items-center justify-between w-full px-3 py-2 border rounded">
          <span>{buttonText}</span>
          <ChevronDown className="w-4 h-4" />
        </button>
      </Popover.Trigger>

      <Popover.Content className="w-64 bg-white border rounded-lg shadow-lg p-2">
        <div className="flex items-center gap-2 mb-2">
          <input
            type="text"
            value={search}
            onChange={e => setSearch(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Search..."
            className="flex-1 px-2 py-1 border rounded"
            autoFocus
          />
          {selected.length > 0 && (
            <button onClick={clearAll} className="text-gray-400 hover:text-gray-600">
              <X className="w-4 h-4" />
            </button>
          )}
        </div>

        <div className="max-h-48 overflow-auto">
          {filteredOptions.map((option, index) => (
            <div
              key={option.value}
              onClick={() => toggleOption(option.value)}
              className={`
                flex items-center gap-2 px-2 py-1 cursor-pointer rounded
                ${index === focusIndex ? 'bg-blue-50' : 'hover:bg-gray-50'}
              `}
            >
              <div className={`
                w-4 h-4 border rounded flex items-center justify-center
                ${selected.includes(option.value) ? 'bg-blue-500 border-blue-500' : ''}
              `}>
                {selected.includes(option.value) && <Check className="w-3 h-3 text-white" />}
              </div>
              <span>{option.label}</span>
            </div>
          ))}
        </div>
      </Popover.Content>
    </Popover.Root>
  );
}
