  });

  const { observerRef } = useInfiniteScroll({
    onLoadMore: fetchNextPage,
    hasMore: !!hasNextPage,
    isLoading: isFetchingNextPage,
  });

  // Maintain scroll position
  useEffect(() => {
    const saved = sessionStorage.getItem('feed_scroll');
    if (saved) {
      window.scrollTo(0, parseInt(saved, 10));
    }

    const handleScroll = () => {
      sessionStorage.setItem('feed_scroll', String(window.scrollY));
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Pull to refresh
  const [isRefreshing, setIsRefreshing] = useState(false);
  const touchStartY = useRef(0);

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartY.current = e.touches[0].clientY;
  };

  const handleTouchEnd = async (e: React.TouchEvent) => {
    const touchEndY = e.changedTouches[0].clientY;
    const pullDistance = touchEndY - touchStartY.current;

    if (window.scrollY === 0 && pullDistance > 100) {
      setIsRefreshing(true);
      await refetch();
      setIsRefreshing(false);
    }
  };

  const items = data?.pages.flatMap(page => page.items) || [];

  return (
    <div onTouchStart={handleTouchStart} onTouchEnd={handleTouchEnd}>
      {isRefreshing && (
        <div className="text-center py-4">
          <Spinner /> Refreshing...
        </div>
      )}

      {items.map(item => <FeedItem key={item.id} item={item} />)}

      {/* Infinite scroll trigger */}
      {hasNextPage && (
        <div ref={observerRef} className="py-4 text-center">
          {isFetchingNextPage && <Spinner />}
        </div>
      )}

      {!hasNextPage && items.length > 0 && (
        <p className="text-center text-gray-500 py-4">No more items</p>
      )}
    </div>
  );
}
