```tsx
import { useState, useRef, useCallback } from 'react';
import axios from 'axios';
import { Upload, X } from 'lucide-react';

interface DropZoneProps {
  accept?: string[];
  maxFiles?: number;
  onUploadComplete?: (urls: string[]) => void;
}

interface FileUpload {
  file: File;
  progress: number;
  status: 'pending' | 'uploading' | 'complete' | 'error';
  url?: string;
  error?: string;
}

export function DropZone({
  accept = ['image/*', 'application/pdf'],
  maxFiles = 10,
  onUploadComplete,
}: DropZoneProps) {
  const [isDragOver, setIsDragOver] = useState(false);
  const [uploads, setUploads] = useState<FileUpload[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  const validateFile = (file: File): string | null => {
    const isValidType = accept.some(type => {
      if (type.endsWith('/*')) {
        return file.type.startsWith(type.replace('/*', ''));
      }
      return file.type === type;
    });
    if (!isValidType) return `Invalid file type: ${file.type}`;
    return null;
  };

  const uploadFile = async (file: File, index: number) => {
    const formData = new FormData();
    formData.append('file', file);

    try {
      const response = await axios.post('/api/upload', formData, {
        onUploadProgress: (e) => {
          const progress = Math.round((e.loaded * 100) / (e.total || 1));
          setUploads(prev => prev.map((u, i) =>
            i === index ? { ...u, progress, status: 'uploading' } : u
          ));
        },
      });

      setUploads(prev => prev.map((u, i) =>
        i === index ? { ...u, status: 'complete', url: response.data.url } : u
      ));
    } catch (error) {
      setUploads(prev => prev.map((u, i) =>
        i === index ? { ...u, status: 'error', error: 'Upload failed' } : u
      ));
    }
  };

  const handleFiles = useCallback((files: FileList) => {
    const newUploads: FileUpload[] = [];

    Array.from(files).slice(0, maxFiles).forEach(file => {
      const error = validateFile(file);
      newUploads.push({
        file,
        progress: 0,
        status: error ? 'error' : 'pending',
        error: error || undefined,
      });
    });

    setUploads(prev => [...prev, ...newUploads]);

    newUploads.forEach((upload, i) => {
      if (upload.status !== 'error') {
        uploadFile(upload.file, uploads.length + i);
      }
    });
  }, [uploads.length, maxFiles]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    handleFiles(e.dataTransfer.files);
  };

  const removeUpload = (index: number) => {
    setUploads(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div>
      <div
        onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
        onDragLeave={() => setIsDragOver(false)}
        onDrop={handleDrop}
        onClick={() => inputRef.current?.click()}
        className={`
          border-2 border-dashed rounded-lg p-8 text-center cursor-pointer
          transition-colors
          ${isDragOver ? 'border-blue-500 bg-blue-50' : 'border-gray-300 hover:border-gray-400'}
        `}
      >
        <Upload className="w-8 h-8 mx-auto mb-2 text-gray-400" />
        <p>Drag files here or click to browse</p>
        <p className="text-sm text-gray-500">Accepts: {accept.join(', ')}</p>
      </div>

      <input
        ref={inputRef}
        type="file"
        multiple
        accept={accept.join(',')}
        onChange={(e) => e.target.files && handleFiles(e.target.files)}
        hidden
      />

      {/* Upload list */}
      <div className="mt-4 space-y-2">
        {uploads.map((upload, i) => (
          <div key={i} className="flex items-center gap-2 p-2 bg-gray-50 rounded">
            <span className="flex-1 truncate">{upload.file.name}</span>
            {upload.status === 'uploading' && (
              <div className="w-24 bg-gray-200 rounded-full h-2">
                <div className="bg-blue-500 h-2 rounded-full" style={{ width: `${upload.progress}%` }} />
              </div>
            )}
            {upload.status === 'complete' && <span className="text-green-500">Done</span>}
            {upload.status === 'error' && <span className="text-red-500">{upload.error}</span>}
            <button onClick={() => removeUpload(i)}><X className="w-4 h-4" /></button>
          </div>
        ))}
      </div>
    </div>
  );
}
```

