import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Comment } from './Comment';
import { CommentForm } from './CommentForm';

export function CommentSection({ postId }: { postId: string }) {
  const queryClient = useQueryClient();

  const { data, isLoading } = useQuery({
    queryKey: ['comments', postId],
    queryFn: () => fetchComments(postId),
    refetchInterval: 30000, // Poll every 30s
  });

  const addCommentMutation = useMutation({
    mutationFn: ({ parentId, content }: { parentId?: string; content: string }) =>
      createComment({ postId, parentId, content }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['comments', postId] });
    },
  });

  const handleAddComment = (content: string) => {
    addCommentMutation.mutate({ content });
  };

  const handleReply = (parentId: string, content: string) => {
    addCommentMutation.mutate({ parentId, content });
  };

  if (isLoading) return <p>Loading comments...</p>;

  return (
    <section>
      <h2 className="text-xl font-semibold mb-4">
        Comments ({data?.total || 0})
      </h2>

      <CommentForm onSubmit={handleAddComment} placeholder="Add a comment..." />

      <div className="mt-6 space-y-4">
        {data?.comments.map(comment => (
          <Comment
            key={comment.id}
            comment={comment}
            depth={0}
            onReply={handleReply}
          />
        ))}
      </div>

      {data?.hasMore && (
        <button className="mt-4 text-blue-600">Load more comments</button>
      )}
    </section>
  );
}
