import { useTranslation } from 'react-i18next';
import { format } from 'date-fns';
import { enUS, es } from 'date-fns/locale';

const locales = { en: enUS, es };

export function useFormatters() {
  const { i18n } = useTranslation();
  const locale = locales[i18n.language] || enUS;

  const formatDate = (date: Date, pattern = 'PPP') => {
    return format(date, pattern, { locale });
  };

  const formatNumber = (num: number, options?: Intl.NumberFormatOptions) => {
    return new Intl.NumberFormat(i18n.language, options).format(num);
  };

  const formatCurrency = (amount: number, currency = 'USD') => {
    return formatNumber(amount, { style: 'currency', currency });
  };

  return { formatDate, formatNumber, formatCurrency };
}
