import { useState, useEffect, useCallback, useRef } from 'react';

const SESSION_DURATION = 30 * 60 * 1000; // 30 minutes
const WARNING_TIME = 5 * 60 * 1000; // 5 minutes before expiry

export function useSessionTimeout(onTimeout: () => void) {
  const [showWarning, setShowWarning] = useState(false);
  const [timeRemaining, setTimeRemaining] = useState(0);
  const expiryRef = useRef(Date.now() + SESSION_DURATION);
  const warningTimerRef = useRef<NodeJS.Timeout>();
  const countdownRef = useRef<NodeJS.Timeout>();

  const resetTimer = useCallback(() => {
    expiryRef.current = Date.now() + SESSION_DURATION;
    setShowWarning(false);

    // Clear existing timers
    if (warningTimerRef.current) clearTimeout(warningTimerRef.current);
    if (countdownRef.current) clearInterval(countdownRef.current);

    // Set warning timer
    warningTimerRef.current = setTimeout(() => {
      setShowWarning(true);
      setTimeRemaining(WARNING_TIME);

      // Start countdown
      countdownRef.current = setInterval(() => {
        const remaining = expiryRef.current - Date.now();
        if (remaining <= 0) {
          clearInterval(countdownRef.current);
          onTimeout();
        } else {
          setTimeRemaining(remaining);
        }
      }, 1000);
    }, SESSION_DURATION - WARNING_TIME);
  }, [onTimeout]);

  // Activity listeners
  useEffect(() => {
    const events = ['mousedown', 'keydown', 'scroll', 'touchstart'];
    const handleActivity = () => {
      if (!showWarning) {
        resetTimer();
      }
    };

    events.forEach(event => window.addEventListener(event, handleActivity));
    resetTimer();

    return () => {
      events.forEach(event => window.removeEventListener(event, handleActivity));
      if (warningTimerRef.current) clearTimeout(warningTimerRef.current);
      if (countdownRef.current) clearInterval(countdownRef.current);
    };
  }, [resetTimer, showWarning]);

  const extendSession = useCallback(async () => {
    await fetch('/api/auth/refresh', { method: 'POST' });
    resetTimer();
  }, [resetTimer]);

  return { showWarning, timeRemaining, extendSession };
}
