import { useState } from 'react';
import { format, addDays, setHours, setMinutes } from 'date-fns';

interface SchedulePickerProps {
  value: Date | null;
  onChange: (date: Date | null) => void;
  minDate?: Date;
}

export function SchedulePicker({ value, onChange, minDate = new Date() }: SchedulePickerProps) {
  const [date, setDate] = useState(value ? format(value, 'yyyy-MM-dd') : '');
  const [time, setTime] = useState(value ? format(value, 'HH:mm') : '09:00');

  const handleChange = (newDate: string, newTime: string) => {
    if (newDate && newTime) {
      const [hours, minutes] = newTime.split(':').map(Number);
      const scheduled = setMinutes(setHours(new Date(newDate), hours), minutes);
      onChange(scheduled);
    } else {
      onChange(null);
    }
  };

  const quickOptions = [
    { label: 'Tomorrow 9am', date: setHours(addDays(new Date(), 1), 9) },
    { label: 'Next week', date: setHours(addDays(new Date(), 7), 9) },
  ];

  return (
    <div className="space-y-2">
      <div className="flex gap-2">
        <input
          type="date"
          value={date}
          min={format(minDate, 'yyyy-MM-dd')}
          onChange={e => { setDate(e.target.value); handleChange(e.target.value, time); }}
          className="border rounded px-2 py-1"
        />
        <input
          type="time"
          value={time}
          onChange={e => { setTime(e.target.value); handleChange(date, e.target.value); }}
          className="border rounded px-2 py-1"
        />
      </div>
      <div className="flex gap-2">
        {quickOptions.map(opt => (
          <button
            key={opt.label}
            onClick={() => onChange(opt.date)}
            className="text-sm text-blue-600 hover:underline"
          >
            {opt.label}
          </button>
        ))}
      </div>
    </div>
  );
}
