### Tests
```tsx
it('copies text to clipboard', async () => {
  const writeText = jest.fn();
  Object.assign(navigator, { clipboard: { writeText } });

  render(<CopyButton text="test content" />);
  fireEvent.click(screen.getByRole('button'));

  expect(writeText).toHaveBeenCalledWith('test content');
});

it('shows success feedback after copy', async () => {
  render(<CopyButton text="test" />);
  fireEvent.click(screen.getByRole('button'));

  expect(screen.getByText('Copied!')).toBeInTheDocument();
  expect(screen.getByLabelText('Copied!')).toBeInTheDocument();
});

it('resets feedback after timeout', async () => {
  jest.useFakeTimers();
  render(<CopyButton text="test" label="Code" />);
  fireEvent.click(screen.getByRole('button'));

  expect(screen.getByText('Copied!')).toBeInTheDocument();

  jest.advanceTimersByTime(2000);
  expect(screen.getByText('Code')).toBeInTheDocument();
});

it('uses fallback for browsers without Clipboard API', async () => {
  delete navigator.clipboard;
  const execCommand = jest.spyOn(document, 'execCommand');

  render(<CopyButton text="test" />);
  fireEvent.click(screen.getByRole('button'));

  expect(execCommand).toHaveBeenCalledWith('copy');
});

it('has accessible label', () => {
  render(<CopyButton text="test" label="API Key" />);
  expect(screen.getByLabelText('Copy API Key to clipboard')).toBeInTheDocument();
});
